// GENERATED COPY of public/js/email-layout-core.js for the Cloud Functions
// runtime (Node 20 cannot require an ES module). Do not edit by hand: edit the
// browser module, then regenerate with
//   node scripts/build-email-layout-server.cjs
// tests/email-layout.test.mjs fails if the two drift apart.

// The branded campaign email: one renderer for the campaign editor's live
// preview, the "Send test to me" button and the real send, so what the admin
// previews is byte for byte what the list receives.
//
// The body is written as plain text with five small conventions, chosen so a
// campaign reads fine even in the plain-text part of the message:
//
//   blank line            new paragraph
//   # Heading             a large bold line
//   - item                consecutive lines become a list with a red bar
//   [Label](https://...)  on a line of its own: a red button. Inside a
//                         sentence: a link.
//   **words**             bold
//
// Bare https:// URLs become links. Everything else is escaped, so nothing an
// admin types can inject markup into the message.
//
// Email clients are hostile to modern CSS. Gmail drops the `background`
// shorthand and every <img> it does not trust, so colours are set twice
// (bgcolor attribute and background-color) and the layout is tables. The
// server copy is functions/email-layout-core.js, generated by
//   node scripts/build-email-layout-server.cjs

const BRAND = {
  black: '#000000',
  ground: '#0b0b0b',
  white: '#ffffff',
  ink: '#1a1a1a',
  muted: '#666666',
  panel: '#f4f4f4',
  red: '#e60306',
  blue: '#155eef'
};

const TAGLINE = 'Redefining Success. Realigning Purpose. Releasing Potential.';

// Used when a campaign carries no signature of its own.
const DEFAULT_SIGNATURE = [
  'Anthony Brown Sr.',
  'Founder, The One Percent Nation',
  'Keynote Speaker | Leadership Coach | Financial Alignment Coach',
  'https://the1pnation.com · [anthonybrown@the1pnation.com](mailto:anthonybrown@the1pnation.com)',
  '[Book a Free Alignment Audit](https://the1pnation.com/book-a-call)'
].join('\n');

// The headshot beside the signature: the same hosted image as Anthony's
// Gmail signature, so every email he sends looks like it came from him.
const HEADSHOT = 'https://the1pnation.com/assets/email/anthony-brown-headshot.jpg';

// The placeholder sendCampaign swaps for each recipient's opt-out link.
const UNSUBSCRIBE_PLACEHOLDER = '-unsubscribe_url-';

const SANS = "'DM Sans',Arial,Helvetica,sans-serif";
const BODY = 'Montserrat,Arial,Helvetica,sans-serif';

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

// Only web links and mail links ever reach an href or src.
function safeUrl(u) {
  const s = String(u || '').trim();
  return /^(https?:\/\/|mailto:)[^\s"<>]+$/i.test(s) ? s : '';
}

const BUTTON_LINE = /^\[([^\]\n]+)\]\(([^)\s]+)\)$/;
const INLINE_LINK = /\[([^\]\n]+)\]\(([^)\s]+)\)/g;

// Inline formatting on one already-trimmed line of text. Links are cut out
// first so their URLs are not escaped twice or auto-linked again.
function inline(text, { underline = true } = {}) {
  const deco = underline ? 'underline' : 'none';
  const parts = [];
  let last = 0;
  const src = String(text);
  src.replace(INLINE_LINK, (m, label, url, at) => {
    parts.push({ text: src.slice(last, at) });
    parts.push({ label, url });
    last = at + m.length;
    return m;
  });
  parts.push({ text: src.slice(last) });
  return parts.map((p) => {
    if (p.label != null) {
      const href = safeUrl(p.url);
      const label = bold(esc(p.label));
      return href ? `<a href="${esc(href)}" style="color:${BRAND.blue};text-decoration:${deco};">${label}</a>` : label;
    }
    const withLinks = esc(p.text).replace(/https?:\/\/[^\s<]+/g, (u) => {
      const trimmed = u.replace(/[.,;:!?)]+$/, '');
      const tail = u.slice(trimmed.length);
      const shown = trimmed.replace(/^https?:\/\//, '').replace(/\?.*$/, '').replace(/\/$/, '');
      return `<a href="${trimmed}" style="color:${BRAND.blue};text-decoration:${deco};">${shown}</a>${tail}`;
    });
    return bold(withLinks);
  }).join('');
}

function bold(html) {
  return html.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
}

// Body text to blocks: paragraph, heading, list, button.
function parseBody(text) {
  const blocks = [];
  const lines = String(text || '').replace(/\r\n?/g, '\n').split('\n');
  let para = [];
  let list = null;
  const flushPara = () => { if (para.length) blocks.push({ type: 'p', lines: para }); para = []; };
  const flushList = () => { if (list) blocks.push({ type: 'list', items: list }); list = null; };
  for (const raw of lines) {
    const line = raw.trim();
    if (!line) { flushPara(); flushList(); continue; }
    const btn = line.match(BUTTON_LINE);
    if (btn && safeUrl(btn[2])) { flushPara(); flushList(); blocks.push({ type: 'button', label: btn[1], url: safeUrl(btn[2]) }); continue; }
    if (/^#\s+/.test(line)) { flushPara(); flushList(); blocks.push({ type: 'h', text: line.replace(/^#\s+/, '') }); continue; }
    if (/^[-*•]\s+/.test(line)) { flushPara(); (list = list || []).push(line.replace(/^[-*•]\s+/, '')); continue; }
    flushList();
    para.push(line);
  }
  flushPara(); flushList();
  return blocks;
}

function firstButtonUrl(text) {
  const b = parseBody(text).find((x) => x.type === 'button');
  return b ? b.url : '';
}

function row(inner, { pad = '0 40px 22px', bg = BRAND.white, align = 'left', extra = '' } = {}) {
  return `<tr><td align="${align}" bgcolor="${bg}" style="background-color:${bg};padding:${pad};${extra}">${inner}</td></tr>`;
}

function blockHtml(b) {
  const text = `font-family:${BODY};font-size:16px;line-height:1.65;color:${BRAND.ink};`;
  if (b.type === 'p') return row(`<div style="${text}">${b.lines.map((l) => inline(l)).join('<br>')}</div>`);
  if (b.type === 'h') {
    return row(`<div style="font-family:${SANS};font-size:22px;line-height:1.35;font-weight:700;color:${BRAND.black};">${inline(b.text)}</div>`, { pad: '6px 40px 22px' });
  }
  if (b.type === 'list') {
    const items = b.items.map((it, i) =>
      `<div style="${text}padding-bottom:${i === b.items.length - 1 ? 0 : 10}px;">${inline(it)}</div>`).join('');
    return row(`<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>`
      + `<td width="4" bgcolor="${BRAND.red}" style="background-color:${BRAND.red};width:4px;font-size:0;line-height:0;">&nbsp;</td>`
      + `<td style="padding:4px 0 4px 18px;">${items}</td></tr></table>`);
  }
  if (b.type === 'button') {
    return row(`<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>`
      + `<td align="center" bgcolor="${BRAND.red}" style="background-color:${BRAND.red};border-radius:4px;">`
      + `<a href="${esc(b.url)}" target="_blank" style="display:inline-block;padding:16px 30px;font-family:${SANS};font-size:15px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:${BRAND.white};text-decoration:none;border-radius:4px;">${esc(b.label)}</a>`
      + `</td></tr></table>`, { align: 'center', pad: '8px 40px 30px' });
  }
  return '';
}

// The signature panel: headshot on the left, the lines on the right. The
// first line is the name; the first plain line after it is the title; any
// further plain lines are roles, set small and gray with "|" kept as the
// divider; a line with a link is a contact line; a lone [Label](url) line is
// a black button.
function signatureHtml(signature) {
  const lines = String(signature || '').replace(/\r\n?/g, '\n').split('\n').map((l) => l.trim()).filter(Boolean);
  if (!lines.length) return '';
  const [name, ...rest] = lines;
  const out = [`<div style="font-family:${SANS};font-size:20px;line-height:24px;font-weight:700;color:${BRAND.black};">${inline(name)}</div>`];
  let titled = false;
  rest.forEach((l) => {
    const btn = l.match(BUTTON_LINE);
    if (btn && safeUrl(btn[2])) {
      out.push(`<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin-top:14px;"><tr>`
        + `<td bgcolor="${BRAND.black}" style="background-color:${BRAND.black};border-radius:3px;padding:9px 14px;">`
        + `<a href="${esc(safeUrl(btn[2]))}" target="_blank" style="font-family:${SANS};font-size:13px;line-height:16px;font-weight:700;color:${BRAND.white};text-decoration:none;letter-spacing:0.4px;">${esc(btn[1])} <span style="color:${BRAND.red};">&rarr;</span></a>`
        + `</td></tr></table>`);
    } else if (/https?:\/\/|\]\(/.test(l)) {
      out.push(`<div style="font-size:13px;line-height:20px;padding-top:8px;">${inline(l, { underline: false })}</div>`);
    } else if (!titled) {
      titled = true;
      out.push(`<div style="font-family:${SANS};font-size:14px;line-height:20px;font-weight:600;color:${BRAND.black};padding-top:2px;">${inline(l)}</div>`);
    } else {
      // Two roles to a line, so a divider never dangles at a wrap.
      const roles = l.split(/\s*\|\s*/).filter(Boolean).map((r) => `<span style="white-space:nowrap;">${inline(r)}</span>`);
      const rows = [];
      for (let i = 0; i < roles.length; i += 2) rows.push(roles.slice(i, i + 2).join(' &nbsp;|&nbsp; '));
      out.push(`<div style="font-family:${SANS};font-size:11px;line-height:17px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:${BRAND.muted};padding-top:4px;">${rows.join('<br>')}</div>`);
    }
  });
  return `<tr><td class="sig-panel" bgcolor="${BRAND.panel}" style="background-color:${BRAND.panel};padding:28px 40px;border-top:3px solid ${BRAND.black};font-family:${BODY};font-size:14px;line-height:1.6;color:${BRAND.ink};">`
    + `<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>`
    + `<td class="sig-photo" valign="top" width="112" style="width:112px;min-width:112px;padding:0 18px 0 0;vertical-align:top;"><img src="${HEADSHOT}" width="112" height="112" alt="${esc(name)}" style="display:block;width:112px;min-width:112px;max-width:112px;height:112px;border-radius:56px;border:0;"></td>`
    + `<td class="sig-text" valign="top" style="padding:0 0 0 18px;vertical-align:top;border-left:2px solid ${BRAND.black};">${out.join('')}</td>`
    + `</tr></table></td></tr>`;
}

/**
 * The full HTML document for one campaign.
 *
 * { bodyText, subject, preheader, heroImageUrl, heroAlt, heroLink, signature,
 *   unsubscribeUrl }
 *
 * heroLink defaults to the body's first button. signature defaults to
 * DEFAULT_SIGNATURE; pass '' for none. unsubscribeUrl defaults to the
 * placeholder the campaign sender fills per recipient.
 */
function renderCampaignEmail(opts = {}) {
  const bodyText = opts.bodyText || '';
  const hero = safeUrl(opts.heroImageUrl);
  const heroLink = safeUrl(opts.heroLink) || firstButtonUrl(bodyText);
  const signature = opts.signature == null ? DEFAULT_SIGNATURE : opts.signature;
  const unsub = opts.unsubscribeUrl || UNSUBSCRIBE_PLACEHOLDER;
  const preheader = String(opts.preheader || '').trim();

  const heroImg = hero
    ? `<img src="${esc(hero)}" width="600" alt="${esc(opts.heroAlt || '')}" style="display:block;width:100%;max-width:600px;height:auto;border:0;">`
    : '';
  const heroRow = hero
    ? `<tr><td bgcolor="${BRAND.black}" style="background-color:${BRAND.black};font-size:0;line-height:0;">${heroLink ? `<a href="${esc(heroLink)}" target="_blank" style="display:block;">${heroImg}</a>` : heroImg}</td></tr>`
    : `<tr><td bgcolor="${BRAND.red}" style="background-color:${BRAND.red};height:3px;font-size:0;line-height:0;">&nbsp;</td></tr>`;

  const blocks = parseBody(bodyText).map(blockHtml).join('');

  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light only"><title>${esc(opts.subject || '')}</title>
<style>@media only screen and (max-width:480px){.sig-panel{padding:24px 20px!important}.sig-photo,.sig-text{display:block!important;width:auto!important}.sig-text{border-left:0!important;padding:16px 0 0!important}}</style></head>
<body style="margin:0;padding:0;background-color:${BRAND.ground};">
${preheader ? `<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${esc(preheader)}</div>` : ''}
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${BRAND.ground}" style="background-color:${BRAND.ground};"><tr><td align="center" bgcolor="${BRAND.ground}" style="background-color:${BRAND.ground};padding:24px 12px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;">
<tr><td align="center" style="padding:8px 0 20px;font-family:${SANS};font-size:13px;letter-spacing:4px;font-weight:700;color:${BRAND.white};text-transform:uppercase;">The One Percent <span style="color:${BRAND.red};">Nation</span></td></tr>
${heroRow}
${row('', { pad: '36px 40px 0' })}
${blocks}
${row('', { pad: '0 40px 14px' })}
${signatureHtml(signature)}
<tr><td align="center" style="padding:26px 20px 8px;font-family:${SANS};font-size:12px;letter-spacing:2px;text-transform:uppercase;color:${BRAND.white};">${TAGLINE}</td></tr>
<tr><td align="center" style="padding:0 20px 16px;font-family:${BODY};font-size:11px;line-height:1.6;color:#8a8a8a;">You are receiving this because you signed up with The One Percent Nation.<br><a href="${esc(unsub)}" style="color:#8a8a8a;text-decoration:underline;">Unsubscribe from these emails</a></td></tr>
</table></td></tr></table>
</body></html>`;
}

// The plain-text part of the same message.
function campaignPlainText(opts = {}) {
  const toText = (s) => String(s || '')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((l) => {
      const t = l.trim();
      const btn = t.match(BUTTON_LINE);
      if (btn) return `${btn[1]}: ${btn[2]}`;
      return t.replace(/^#\s+/, '').replace(INLINE_LINK, '$1: $2').replace(/\*\*([^*\n]+)\*\*/g, '$1');
    })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  const signature = opts.signature == null ? DEFAULT_SIGNATURE : opts.signature;
  const unsub = opts.unsubscribeUrl || UNSUBSCRIBE_PLACEHOLDER;
  return [
    toText(opts.bodyText),
    signature ? toText(signature) : '',
    TAGLINE,
    `You are receiving this because you signed up with The One Percent Nation.\nUnsubscribe: ${unsub}`
  ].filter(Boolean).join('\n\n');
}


module.exports = {
  BRAND, TAGLINE, DEFAULT_SIGNATURE, UNSUBSCRIBE_PLACEHOLDER, safeUrl, parseBody, firstButtonUrl, renderCampaignEmail, campaignPlainText
};
